targets.expr:
sum by (label_workspaces_aipub_ten1010_io_owner) (
  kube_pod_labels{namespace="$namespace", label_workspaces_aipub_ten1010_io_owner="$workspace"}
)

sum (
  kube_pod_labels{label_workspaces_aipub_ten1010_io_owner="$workspace"}
  * on (namespace, pod, uid) group_left(phase, condition)
  (kube_pod_status_phase{phase="Pending"} == 1)
) or vector(0)

kube_pod_info{namespace="$namespace"}
* on (namespace, pod, uid) group_left(label_workspaces_aipub_ten1010_io_owner)
kube_pod_labels{label_workspaces_aipub_ten1010_io_owner="$workspace"}
* on (namespace, pod, uid) group_left(condition)
(kube_pod_status_ready{namespace="$namespace"} == 1)
* on (namespace, pod, uid) group_left(reason)
(
  kube_pod_container_status_running{
    namespace="$namespace", container=~"$workspace.*"
  } == 1
  or
  on (namespace, pod, uid) kube_pod_container_status_waiting_reason{
    namespace="$namespace", container=~"$workspace.*"
  } == 1
  or
  on (namespace, pod, uid) kube_pod_container_status_waiting_reason{
    namespace="$namespace", container=~"$workspace.*"
  } == 1
)

sum by (Hostname, gpu, UUID, modelName, exported_namespace, exported_pod) (
  label_replace(
    GPU_POD_UTIL_LIMIT{exported_namespace="$namespace", UUID=~"GPU.*"}
    * on (exported_namespace, exported_pod) group_left()
    label_replace(
      label_replace(
        kube_pod_labels{namespace="$namespace", label_workspaces_aipub_ten1010_io_owner="$workspace"}
        * on (namespace, pod) group_left()
        (kube_pod_status_ready{namespace="$namespace", condition="true"} == 1)
        , "exported_namespace", "$1", "namespace", "(.*)"
      ), "exported_pod", "$1", "pod", "(.*)"
    )
    , "Hostname", "$1", "node", "(.*)"
  )
)
* on (Hostname, gpu, UUID, GPU_I_ID) group_left(device, modelName)
sgn(gpu:resource:gpu_temp)
or
sum by (Hostname, gpu, UUID, GPU_I_ID, MIG_UUID, exported_namespace, exported_pod) (
  MIG_POD_ALLOCATED{exported_namespace="$namespace"}
  * on (exported_namespace, exported_pod) group_left()
  label_replace(
    label_replace(
      kube_pod_labels{namespace="$namespace", label_workspaces_aipub_ten1010_io_owner="$workspace"}
      * on (namespace, pod) group_left()
      (kube_pod_status_ready{namespace="$namespace", condition="true"} == 1)
      , "exported_namespace", "$1", "namespace", "(.*)"
    ), "exported_pod", "$1", "pod", "(.*)"
  )
)
* on(Hostname, gpu, UUID, GPU_I_ID) group_left(device, modelName, GPU_I_PROFILE)
sgn(gpu:resource:gpu_temp)

sum by (namespace, pod) (
  rate(container_cpu_usage_seconds_total{namespace="$namespace", container!="", image!=""}[5m])
  * on (namespace, pod) group_left()
  kube_pod_labels{namespace="$namespace", label_workspaces_aipub_ten1010_io_owner="$workspace"}
)

sum by (namespace, pod) (
  container_memory_working_set_bytes{namespace="$namespace", container!="", image!=""}
  * on(namespace, pod) group_left(label_workspaces_aipub_ten1010_io_owner)
  kube_pod_labels{namespace=~"$namespace", label_workspaces_aipub_ten1010_io_owner="$workspace"}
)

